 "영구 삭제": "Hapus permanen",
 "사람 이름이나 메일 주소처럼 지우고 싶은 말을 넣으면, 그 말이 들어간 기억과 원본 기록을 모두 찾아 영구히 지워요. 먼저 몇 개인지 보여 드려요.": "Masukkan kata yang ingin dihapus, seperti nama orang atau alamat email. Arkism akan mencari semua memori dan catatan asli yang memuatnya, lalu menghapusnya secara permanen. Jumlahnya ditampilkan dulu.",
