 "노드를 누르면 여기서 고쳐요. 출력 점을 끌어 다음 노드에 이어요. 앞 노드로 이으면 되돌아가는 선이 돼요. 선을 누르면 선 설정이 열려요. 휠로 확대·축소하고, 휠 클릭이나 스페이스를 누른 채 끌면 화면이 움직여요.": "Klik node untuk mengeditnya di sini. Seret titik keluaran untuk menyambung ke node berikutnya. Jika disambung ke node sebelumnya, jadilah garis yang kembali. Klik garis untuk membuka pengaturannya. Putar roda untuk memperbesar/memperkecil, dan klik roda atau tahan Spasi sambil menyeret untuk menggeser layar.",
