 "이름·모델·프롬프트를 적어 주세요. 제외할 것이나 스크립트는 오른쪽에서 더할 수 있어요. {변수}처럼 중괄호로 쓰면 변수가 돼요.": "Isi nama, model, dan prompt. Pengecualian atau skrip bisa ditambahkan di sebelah kanan. Tulis dengan kurung kurawal seperti {variabel} agar menjadi variabel.",
 "AI로 이름 짓기": "Beri nama dengan AI",
 "파일을 고르거나 이미지를 붙여 넣어요. 저장할 때 512KB 이하 WebP로 줄여요.": "Pilih file atau tempel gambar. Saat disimpan, gambar diperkecil menjadi WebP di bawah 512KB.",
 "추가 설정": "Pengaturan tambahan",
 "비워 두면 모델 기본값으로 만들어요.": "Kosongkan untuk memakai bawaan model.",
 "이름·출처·색·글꼴을 적고, 오른쪽에 쓰는 법과 규칙을 남겨 주세요. 키·토큰은 넣지 마세요.": "Isi nama, sumber, warna, dan font, lalu tulis cara pakai dan aturannya di sebelah kanan. Jangan masukkan kunci atau token.",
 "기본 정보": "Info dasar",
 "갤러리 카드에 보이는 이름과 설명이에요. 제품과 목적이 같은 것끼리 묶여요.": "Nama dan deskripsi yang tampil di kartu galeri. Yang produk dan tujuannya sama akan dikelompokkan.",
 "색과 글꼴": "Warna dan font",
 "색은 \"이름 #값\"을 한 줄에 하나씩 적어요.": "Tulis warna dengan format \"nama #nilai\", satu per baris.",
