 "다른 곳에서 수정됐으면 최신 내용을 확인한 뒤 다시 저장하세요.": "Jika diubah di tempat lain, cek isi terbarunya lalu simpan lagi.",
 "영역 메뉴": "Menu area",
 "연결 방법": "Cara menghubungkan",
 "Arkism 서버를 새 버전으로 올리면 디자인 시스템을 저장할 수 있어요.": "Perbarui server Arkism ke versi baru agar sistem desain bisa disimpan.",
 "제품별·목적별로 디자인 시스템을 모아 둬요. 오른쪽 위 ‘디자인 시스템 추가’로 넣고, 이 앱의 실제 색·글자·부품은 ‘Arkism 토큰’에서 봐요.": "Kumpulkan sistem desain per produk atau tujuan. Tambahkan lewat ‘Tambah sistem desain’ di kanan atas, dan lihat warna, huruf, serta komponen asli aplikasi ini di ‘Token Arkism’.",
 "아직 디자인 시스템이 없어요. 제품의 색·글꼴·규칙을 하나씩 추가해 보세요.": "Belum ada sistem desain. Coba tambahkan warna, font, dan aturan produk satu per satu.",
