 "복제하지 못했어요. 이름이나 이미지 크기를 확인해 주세요.": "Tidak bisa diduplikasi. Periksa nama atau ukuran gambar.",
 "복제하지 못했어요. 이름과 색을 확인해 주세요.": "Tidak bisa diduplikasi. Periksa nama dan warna.",
 "쓰는 워크플로우($이름)를 정하면 그 워크플로우가 스크립트를 실행해요.": "Jika Anda menentukan workflow yang dipakai ($nama), workflow itu akan menjalankan skrip.",
