 "‘다시 연결’을 누르거나, 서버의 에이전트에서 /mcp 를 열어 다시 인증해 주세요. 끝나면 1분 안에 여기 반영돼요.": "Tekan ‘Hubungkan ulang’, atau buka /mcp di agen pada server lalu masuk lagi. Hasilnya tampil di sini dalam 1 menit.",
