 "순서대로: 늘 1번 모델로 보내고, 실패하면 다음 모델로 넘겨요.": "Berurutan: selalu dikirim ke model nomor 1, dan jika gagal diteruskan ke model berikutnya.",
 "그룹에 꺼진 모델이 있어요. 모델을 켜거나 그룹에서 빼 주세요.": "Ada model yang mati di grup. Nyalakan modelnya atau keluarkan dari grup.",
