 "전체=다 넣기 · 요약=줄여서 넣기 · 참조=제목만 넣고 필요할 때 읽기 · 고정=그 버전만, 최신=바뀌면 따라가기": "Penuh = masukkan semua · Ringkasan = dipersingkat · Referensi = hanya judul, dibaca saat perlu · Tetap = hanya versi itu, Terbaru = ikut berubah",
