 "중계기 토큰을 다시 만들까요? 에이전트 설정에 새 토큰을 넣어요.": "Buat ulang token gateway? Token baru akan dimasukkan ke pengaturan agen.",
 "새 토큰을 만들고 에이전트 설정에 넣었어요. 중계기를 다시 켜면 예전 토큰은 막혀요.": "Token baru sudah dibuat dan dimasukkan ke pengaturan agen. Token lama akan diblokir setelah gateway dinyalakan ulang.",
