 "새로 들어온 기억이 이미 있는 기억과 비슷해요. AI 제안을 보고 저장할지, 합칠지, 건너뛸지 골라 주세요.": "Memori baru yang masuk mirip dengan memori yang sudah ada. Lihat saran AI, lalu pilih untuk menyimpan, menggabungkan, atau melewati.",
