 "요약을 불러오는 중…": "Memuat ringkasan…",
 "검색과 맞는 주제가 없어요.": "Tidak ada topik yang cocok dengan pencarian.",
 "아직 주제 요약이 없어요. 승인된 기억이 쌓이면 밤사이 제안돼요.": "Belum ada ringkasan topik. Setelah memori yang disetujui menumpuk, akan disarankan semalaman.",
