 "여기에 표시할 요약이 없어요.": "Tidak ada ringkasan untuk ditampilkan di sini.",
 "· 최대 개수에 닿아서 합치기 제안이 나올 수 있어요": "· Sudah mencapai jumlah maksimum, jadi saran penggabungan bisa muncul",
 "나에 대한 요약": "Ringkasan tentang saya",
 "바탕 기억이 바뀌거나 지워져 쓸 수 없어요. 다음 실행 때 다시 제안돼요.": "Memori dasarnya berubah atau dihapus, jadi tidak bisa dipakai. Akan disarankan lagi pada proses berikutnya.",
 "아직 쓰는 요약은 없어요. 후보를 확인해 주세요.": "Belum ada ringkasan yang dipakai. Silakan periksa calonnya.",
 "아직 요약이 없어요. 나에 대한 기억이 승인되면 제안돼요.": "Belum ada ringkasan. Akan disarankan setelah memori tentang Anda disetujui.",
 "주제를 고르세요": "Pilih topik",
 "비슷한 기억을 묶은 요약이에요. 사실이나 지시가 아니라 참고 자료로 쓰여요.": "Ringkasan dari memori yang mirip. Dipakai sebagai bahan referensi, bukan sebagai fakta atau instruksi.",
