 "묶인 기억": "Memori yang dikelompokkan",
 "질문이 이 주제와 맞을 때": "Saat pertanyaan cocok dengan topik ini",
 "모든 에이전트 · 참고 자료로": "Semua agen · sebagai referensi",
 "승인된 기억으로 AI가 새 주제를 묶었어요. 이 요약을 쓸까요?": "AI mengelompokkan memori yang disetujui menjadi topik baru. Pakai ringkasan ini?",
 "비슷한 두 요약을 하나로 합치자는 후보예요. 합치면 두 요약은 이전 버전으로 남아요.": "Calon yang menggabungkan dua ringkasan serupa menjadi satu. Jika digabung, kedua ringkasan tetap ada sebagai versi lama.",
 "AI가 요약을 고쳤어요. 이 후보로 바꿀까요?": "AI memperbaiki ringkasannya. Ganti dengan draf ini?",
