 "아직 스킬이 없어요. GitHub 주소나 zip 파일로 첫 스킬을 설치해 보세요.": "Belum ada skill. Pasang skill pertama Anda dari alamat GitHub atau file zip.",
 "스킬 설치": "Pasang skill",
 "이 스킬 끄기": "Matikan skill ini",
 "이 스킬 켜기": "Nyalakan skill ini",
 "보안 위험이라 멈춰 있어요. 켜면 에이전트에게 다시 추천해요.": "Dihentikan karena risiko keamanan. Jika dinyalakan, skill ini direkomendasikan lagi ke agen.",
 "지금은 어느 에이전트도 받지 않아요.": "Saat ini tidak ada agen yang menerimanya.",
 "아래 바에서 적용을 눌러야 바뀌어요.": "Tekan Terapkan di bilah bawah agar perubahan berlaku.",
 "자세히 · 에이전트마다 고르기": "Detail · pilih per agen",
 "검사에서 위험한 내용을 찾았어요. 아래에서 직접 켜기 전까지 Arkism이 에이전트에게 추천하지 않아요. 파일은 에이전트 폴더에 남아 있으니, 믿을 수 없으면 휴지통으로 옮기세요.": "Pemeriksaan menemukan isi yang berbahaya. Arkism tidak akan merekomendasikannya ke agen sampai Anda menyalakannya sendiri di bawah. File masih ada di folder agen, jadi pindahkan ke tempat sampah jika Anda tidak memercayainya.",
 "자주 쓰는 서버를 고르거나 주소를 붙여 넣어요. 로그인이 필요한 서버는 추가한 뒤 로그인해요.": "Pilih server yang umum dipakai atau tempel alamatnya. Untuk server yang perlu login, login setelah menambahkannya.",
 "비워 두면 주소에서 정해요": "Kosongkan untuk diambil dari alamat",
 "각 에이전트의 프로그램으로 서버에 추가해요.": "Server ditambahkan lewat program milik masing-masing agen.",
 "자세히 · 이름, 연결 방식, 넣을 에이전트": "Detail · nama, cara koneksi, agen tujuan",
 "키나 토큰이 필요한 서버는 아직 여기서 추가할 수 없어요. 키는 이 칸들에 넣지 마세요.": "Server yang memerlukan kunci atau token belum bisa ditambahkan di sini. Jangan isi kunci di kolom-kolom ini.",
 "원격 서버 주소로 연결해요. 로그인이 필요하면 추가한 뒤 로그인해요.": "Terhubung lewat alamat server jarak jauh. Jika perlu login, login setelah menambahkannya.",
 "키나 토큰처럼 보이는 값이 있어요. 빼고 다시 넣어 주세요. 키가 필요한 서버는 아직 여기서 추가할 수 없어요.": "Ada nilai yang tampak seperti kunci atau token. Hapus lalu masukkan lagi. Server yang memerlukan kunci belum bisa ditambahkan di sini.",
 "MCP 목록을 불러오지 못했어요. 잠시 뒤 새로고침을 눌러 주세요.": "Daftar MCP tidak bisa dimuat. Tekan Segarkan sebentar lagi.",
 "서버의 arkism-agents.timer가 돌고 있는지 확인해 주세요.": "Pastikan arkism-agents.timer berjalan di server.",
 "목록이 5분 넘게 새로 오지 않았어요. 잠시 뒤 새로고침을 눌러 주세요.": "Daftar tidak diperbarui lebih dari 5 menit. Tekan Segarkan sebentar lagi.",
 "아직 플러그인이 없어요. 서버의 Claude Code에서 /plugin 으로 설치하면 1분 안에 여기에 보여요.": "Belum ada plugin. Pasang dengan /plugin di Claude Code pada server, dan plugin akan muncul di sini dalam 1 menit.",
 "아직 MCP 서버가 없어요.": "Belum ada server MCP.",
 "누르면 로그인 창이 열려요. 로그인할 서비스에서 허용하면 서버의 에이전트에 자동으로 적용돼요.": "Jendela login akan terbuka jika ditekan. Setelah Anda mengizinkan di layanan tersebut, otomatis berlaku untuk agen di server.",
 "새 기억 확인 목록을 불러오지 못했어요": "Daftar memori baru untuk diperiksa tidak bisa dimuat",
