 "메모를 남기려면 이유를 하나 골라 주세요.": "Untuk meninggalkan catatan, pilih salah satu alasan.",
 "합치기 제안을 불러오지 못했어요. 새로고침하면 다시 불러와요.": "Saran penggabungan tidak bisa dimuat. Segarkan untuk mencoba lagi.",
 "이 서버는 합치기 제안을 지원하지 않아요.": "Server ini tidak mendukung saran penggabungan.",
 "확인할 합치기 제안이 없어요.": "Tidak ada saran penggabungan untuk diperiksa.",
 "합치기 제안": "Saran penggabungan",
 "합치기 제안 · AI 제안": "Saran penggabungan · Saran AI",
 "지운 기억이에요. 에이전트는 쓰지 않아요. 되살리면 지우기 전처럼 다시 써요.": "Ini memori yang sudah dihapus. Agen tidak memakainya. Jika dipulihkan, dipakai lagi seperti sebelum dihapus.",
 "지웠어요. 「지운 기억」에서 언제든 되살릴 수 있어요.": "Sudah dihapus. Anda bisa memulihkannya kapan saja dari 「Memori dihapus」.",
 "예전 방식으로 저장돼 사람이 승인한 기록이 남지 않은 기억이에요. 할 일은 없고, 내용도 바꾸지 않아요.": "Memori ini disimpan dengan cara lama sehingga tidak ada catatan persetujuan dari seseorang. Tidak ada yang perlu dilakukan, dan isinya tidak diubah.",
 "지운 기억": "Memori dihapus",
 "지운 기억은 에이전트가 쓰지 않아요. 되살리면 다시 써요.": "Agen tidak memakai memori yang dihapus. Jika dipulihkan, dipakai lagi.",
 "아직 기억이 없어요. AI와 대화하면 기억할 만한 내용이 「확인해 주세요」에 올라와요. 직접 적어 둘 수도 있어요.": "Belum ada memori. Saat Anda mengobrol dengan AI, hal yang layak diingat akan muncul di 「Mohon diperiksa」. Anda juga bisa menulisnya sendiri.",
 "지운 기억이 없어요.": "Tidak ada memori yang dihapus.",
