 "코딩 에이전트 채팅에 @이름을 치면 불러요. 부르면 실행기가 그래프대로 돌리고, 부른 자리에는 진행과 결과를 보고해요. AI 칸은 칸마다 정한 모델이 맡아요.": "Ketik @nama di chat agen coding untuk memanggilnya. Setelah dipanggil, runner menjalankan sesuai grafik dan melaporkan progres serta hasilnya di tempat Anda memanggil. Setiap kotak AI dijalankan oleh model yang diatur untuk kotak itu.",
