 "웹훅 주소는 Arkism에 저장하고, 화면에는 끝 4자리만 보여요. 슬랙의 Incoming Webhooks에서 만들어요.": "Alamat webhook disimpan di Arkism, dan di layar hanya 4 karakter terakhir yang terlihat. Buat di Incoming Webhooks Slack.",
